/* Syte boot loader: keep lucide available before app.js.
 *
 * This used to also document.write agent-chat-fixes.js, which index.html
 * loaded as well — so that script ran twice, double-wrapping window.fetch and
 * installing two document-wide MutationObservers. Both observers fired on
 * every streamed chat token, which is a large part of why the agent chat could
 * crash the tab on mobile. The behaviours it patched now live in app.js and
 * style.css, so the script is gone.
 */
document.write('<script src="https://cdn.jsdelivr.net/npm/lucide@0.468.0/dist/umd/lucide.min.js" crossorigin="anonymous"><\/script>');
